def placeholders(text):
    return sorted(re.findall(r"\{\d+\}", text))

def story_keys():
    guides = json.loads((ROOT / "data/ff6/puzzles.json").read_text(encoding="utf-8"))["story_guides"]
    keys = set()
    for guide in guides:
        for value in (guide.get("introduction", ""), guide.get("complete", "")):
            if value: keys.add(value)
        for rule in guide.get("rules", []):
            if rule.get("note"): keys.add(rule["note"])
            for target in rule.get("targets", []):
                if target.get("text"): keys.add(target["text"])
    return keys

def main():
    expected = story_keys() | {"Story guidance is waiting for current game state.", "This story sequence is complete.", "Party {0}", "Party {0}: {1}", "Another party may need to operate a switch. Change parties and request guidance again.", "interact to cross", "Opera action: confirm now."}
    missing = expected - ROWS.keys()
    extra = ROWS.keys() - expected
    if missing or extra:
        raise SystemExit(f"source/catalog key mismatch; missing={sorted(missing)!r}, extra={sorted(extra)!r}")
    for source, row in ROWS.items():
        if len(row) != len(LANGS): raise ValueError(f"{source!r}: expected 12 translations")
        for lang, translated in zip(LANGS, row):
            if placeholders(source) != placeholders(translated):
                raise ValueError(f"placeholder mismatch for {source!r} in {lang}: {translated!r}")
    path = ROOT / "data/common/mod_text.json"
    original = path.read_text(encoding="utf-8")
    catalog = json.loads(original)
    additions = {}
    for source, row in ROWS.items():
        # Existing keys are authoritative; adding a key never rewrites or
        # normalizes any pre-existing catalog entry or translation.
        if source not in catalog:
            additions[source] = dict(zip(LANGS, row))
    if additions:
        insertion = json.dumps(additions, ensure_ascii=False, indent=2)[2:-2]
        closing = original.rfind("}")
        prefix = original[:closing].rstrip()
        separator = "," if prefix.endswith("}") else ""
        path.write_text(prefix + separator + "\n" + insertion + "\n}\n", encoding="utf-8")
        catalog.update(additions)
    for source in expected:
        entry = catalog.get(source)
        if not isinstance(entry, dict): raise ValueError(f"missing catalog entry: {source!r}")
        for lang in LANGS:
            translated = entry.get(lang)
            if not isinstance(translated, str) or not translated.strip():
                raise ValueError(f"empty/missing translation for {source!r} in {lang}")
            if placeholders(source) != placeholders(translated):
                raise ValueError(f"catalog placeholder mismatch for {source!r} in {lang}: {translated!r}")
    print(f"Authored {len(additions)} new FF6 story keys; verified {len(expected)} required entries across {len(LANGS)} locales in {path}")

if __name__ == "__main__": main()
